3	import com.example.starter.survey.domain.IdempotentRecord;
4	import org.springframework.dao.DuplicateKeyException;
5	import org.springframework.jdbc.core.JdbcTemplate;
6	import org.springframework.jdbc.core.RowMapper;
7	import org.springframework.stereotype.Repository;
8	
9	import java.sql.Timestamp;
10	import java.time.Instant;
11	import java.util.Optional;
12	
13	/**
14	 * 幂等记录数据访问。
15	 * requestId 为唯一键：并发首插只有一个成功（{@link DuplicateKeyException}），唯一受理。
16	 */
17	@Repository
18	public class IdempotencyRepository {
19	
20	    /** 占位状态：已占键但业务结果尚未回填。 */
21	    public static final int STATUS_PENDING = 0;
22	
23	    private final JdbcTemplate jdbc;
24	
25	    public IdempotencyRepository(JdbcTemplate jdbc) {
26	        this.jdbc = jdbc;
27	    }
28	
29	    private static final RowMapper<IdempotentRecord> MAPPER = (rs, n) -> new IdempotentRecord(
30	            rs.getLong("id"),
31	            rs.getString("request_id"),
32	            rs.getString("fingerprint"),
33	            rs.getInt("http_status"),
34	            rs.getString("response_body"),
35	            rs.getTimestamp("created_at").toInstant()
36	    );
37	
38	    /** 按 requestId 查询历史记录。 */
39	    public Optional<IdempotentRecord> find(String requestId) {
40	        return jdbc.query("SELECT * FROM idempotent_record WHERE request_id = ?",
41	                        MAPPER, requestId)
42	                .stream().findFirst();
43	    }
44	
45	    /**
46	     * 抢占新 requestId（先占位，业务成功后由 {@link #complete} 回填结果）。
47	     *
48	     * @return true 表示抢占成功（首次）；false 表示键已存在（并发落败或重放）
49	     */
50	    public boolean reserve(String requestId, String fingerprint, Instant now) {
51	        try {
52	            jdbc.update("""
53	                            INSERT INTO idempotent_record
54	                                (request_id, fingerprint, http_status, response_body, created_at)
55	                            VALUES (?, ?, ?, '', ?)
56	                            """,
57	                    requestId, fingerprint, STATUS_PENDING, Timestamp.from(now));
58	            return true;
59	        } catch (DuplicateKeyException e) {
60	            return false;
61	        }
62	    }
