26	import org.springframework.stereotype.Service;
27	
28	import java.time.LocalDate;
29	import java.util.LinkedHashMap;
30	import java.util.List;
31	import java.util.Map;
32	
33	/** 检验申请受理与登轮检验。 */
34	@Service
35	public class SurveyService {
36	
37	    /** 签发终态后迟到登轮记录的事件类型。 */
38	    public static final String EVENT_LATE_BOARD_RECORD = "LATE_BOARD_RECORD";
39	
40	    private final SurveyRepository surveyRepository;
41	    private final ShipRepository shipRepository;
42	    private final DefectRepository defectRepository;
43	    private final SurveyEventRepository eventRepository;
44	    private final IdempotentExecutor executor;
45	
46	    public SurveyService(SurveyRepository surveyRepository,
47	                         ShipRepository shipRepository,
48	                         DefectRepository defectRepository,
49	                         SurveyEventRepository eventRepository,
50	                         IdempotentExecutor executor) {
51	        this.surveyRepository = surveyRepository;
52	        this.shipRepository = shipRepository;
53	        this.defectRepository = defectRepository;
54	        this.eventRepository = eventRepository;
55	        this.executor = executor;
56	    }
57	
58	    /**
59	     * 申请检验（计划→申请）。受理条件（UTC 日界）：
60	     * 今天落在该类型当前窗口闭区间内（恰在窗口首日/末日均可）；
61	     * 同船同类型无其他进行中检验（唯一索引兜底，并发唯一受理）。
62	     */
63	    public ApiResult<SurveyResponse> apply(ApplySurveyRequest request) {
64	        Ship ship = shipRepository.findByImo(request.shipImo())
65	                .orElseThrow(() -> new NotFoundException("SHIP_NOT_FOUND",
66	                        "船舶不存在: " + request.shipImo()));
67	        SurveyType type = request.type();
68	
69	        String fp = Fingerprint.of(request.requestId(), "APPLY_SURVEY",
70	                Map.of("shipImo", request.shipImo(), "type", type.name()));
71	        return executor.run(request.requestId(), fp, SurveyResponse.class, () -> {
72	            LocalDate nowUtc = LocalDate.ofInstant(executor.now(), java.time.ZoneOffset.UTC);
73	            SurveyWindow window = SurveyWindowCalculator
74	                    .windowContaining(ship, type, nowUtc)
75	                    .orElseThrow(() -> new BusinessRuleException("OUTSIDE_WINDOW",
76	                            "当前日期不在" + typeName(type) + "检验窗口内（UTC，首尾含当日）"));
77	            surveyRepository.findInProgress(ship.id(), type).ifPresent(s -> {
78	                throw new ConflictException("SURVEY_IN_PROGRESS",
79	                        "同一船舶同一检验类型已有进行中检验: surveyId=" + s.id());
80	            });
81	            try {
82	                Survey survey = surveyRepository.insert(
83	                        request.requestId(), ship.id(), type,
84	                        window.anchor(), window.start(), window.end(),
85	                        fp, executor.now());
86	                return SurveyResponse.from(survey, ship.imo());
87	            } catch (SurveyRepository.ActiveSurveyConflict e) {
88	                throw new ConflictException("SURVEY_IN_PROGRESS",
89	                        "并发申请：同一船舶同一检验类型仅受理一个进行中检验");
90	            }
91	        });
92	    }
93	
94	    /**
95	     * 登轮检验（申请→登轮）。完成日须落在窗口（含已批准展期末日）闭区间内。
96	     * 检验已发证（终态）后迟到的登轮记录只登记 {@link #EVENT_LATE_BOARD_RECORD} 事件。
97	     */
98	    public ApiResult<BoardResponse> board(BoardSurveyRequest request) {
99	        Survey survey = surveyRepository.findById(request.surveyId())
100	                .orElseThrow(() -> new NotFoundException("SURVEY_NOT_FOUND",
101	                        "检验不存在: surveyId=" + request.surveyId()));
102	        Ship ship = shipRepository.findById(survey.shipId()).orElseThrow();
103	
104	        Map<String, Object> fields = new LinkedHashMap<>();
105	        fields.put("surveyId", request.surveyId());
106	        fields.put("completedDate", request.completedDate().toString());
107	        fields.put("defects", request.defects() == null ? List.of()
108	                : request.defects().stream()
109	                .map(d -> Map.of("severity", d.severity().name(),
110	                        "description", d.description(),
111	                        "foundDate", d.foundDate().toString()))
112	                .toList());
