3	import com.example.starter.survey.domain.Certificate;
4	import com.example.starter.survey.domain.CertificateStatus;
5	import com.example.starter.survey.domain.SurveyType;
6	import org.springframework.jdbc.core.JdbcTemplate;
7	import org.springframework.jdbc.core.RowMapper;
8	import org.springframework.stereotype.Repository;
