10	import java.sql.Date;
11	import java.sql.Timestamp;
12	import java.time.Instant;
13	import java.time.LocalDate;
14	import java.util.List;
15	import java.util.Optional;
16	
17	/**
18	 * 证书版本数据访问。
19	 * valid_flag='Y' 配合唯一索引 uq_certificate_valid 保证：
20	 * 按“船＋检验类型”同一时刻至多一张有效证书；新证插入与旧证失效必须同事务完成。
21	 */
22	@Repository
23	public class CertificateRepository {
24	
25	    private final JdbcTemplate jdbc;
26	
27	    public CertificateRepository(JdbcTemplate jdbc) {
28	        this.jdbc = jdbc;
29	    }
30	
31	    private static final RowMapper<Certificate> MAPPER = (rs, n) -> new Certificate(
32	            rs.getLong("id"),
33	            rs.getLong("ship_id"),
34	            SurveyType.valueOf(rs.getString("type")),
35	            rs.getInt("version"),
36	            CertificateStatus.valueOf(rs.getString("status")),
37	            rs.getDate("valid_from").toLocalDate(),
38	            rs.getObject("valid_until") == null ? null : rs.getDate("valid_until").toLocalDate(),
39	            rs.getObject("survey_id") == null ? null : rs.getLong("survey_id"),
40	            rs.getObject("superseded_by") == null ? null : rs.getLong("superseded_by"),
41	            rs.getTimestamp("created_at").toInstant()
42	    );
43	
44	    /** 按主键查找。 */
45	    public Optional<Certificate> findById(long id) {
46	        return jdbc.query("SELECT * FROM certificate WHERE id = ?", MAPPER, id)
47	                .stream().findFirst();
48	    }
49	
50	    /** 查找当前有效证书（不加锁）。 */
51	    public Optional<Certificate> findValid(long shipId, SurveyType type) {
52	        return jdbc.query("""
53	                        SELECT * FROM certificate
54	                        WHERE ship_id = ? AND type = ? AND valid_flag = 'Y'
55	                        """, MAPPER, shipId, type.name())
56	                .stream().findFirst();
57	    }
58	
59	    /**
60	     * 在事务内行锁当前有效证书（FOR UPDATE），用于发证原子交接，避免并发双有效。
61	     */
62	    public Optional<Certificate> findValidForUpdate(long shipId, SurveyType type) {
63	        return jdbc.query("""
64	                        SELECT * FROM certificate
65	                        WHERE ship_id = ? AND type = ? AND valid_flag = 'Y'
66	                        FOR UPDATE
67	                        """, MAPPER, shipId, type.name())
68	                .stream().findFirst();
69	    }
70	
71	    /** 取该“船＋类型”的下一版本号（无历史版本时为 1）。 */
72	    public int nextVersion(long shipId, SurveyType type) {
73	        Integer max = jdbc.queryForObject(
74	                "SELECT COALESCE(MAX(version), 0) FROM certificate WHERE ship_id = ? AND type = ?",
75	                Integer.class, shipId, type.name());
76	        return (max == null ? 0 : max) + 1;
77	    }
78	
79	    /**
80	     * 插入新版本证书。
81	     *
82	     * @param validFlag true 插入即有效（唯一索引槽位须已释放）；false 先挂起再由 {@link #markValid} 生效
83	     */
84	    public Certificate insert(long shipId, SurveyType type, int version,
85	                              CertificateStatus status, LocalDate validFrom, LocalDate validUntil,
86	                              Long surveyId, boolean validFlag, Instant now) {
87	        jdbc.update("""
88	                        INSERT INTO certificate (ship_id, type, version, status, valid_from, valid_until,
89	                                                 survey_id, superseded_by, created_at, valid_flag)
90	                        VALUES (?, ?, ?, ?, ?, ?, ?, NULL, ?, ?)
91	                        """,
92	                shipId, type.name(), version, status.name(),
93	                Date.valueOf(validFrom),
94	                validUntil == null ? null : Date.valueOf(validUntil),
95	                surveyId,
96	                Timestamp.from(now),
97	                validFlag ? "Y" : null);
98	        // 同事务内取该船+类型最新版本行。
99	        return jdbc.query("""
100	                        SELECT * FROM certificate
101	                        WHERE ship_id = ? AND type = ? AND version = ?
102	                        """, MAPPER, shipId, type.name(), version)
103	                .stream().findFirst().orElseThrow();
104	    }
105	
106	    /** 旧证失效：状态 SUPERSEDED、释放唯一索引槽位、记录替代版本。 */
107	    public void markSuperseded(long oldCertificateId, long newCertificateId) {
108	        int updated = jdbc.update("""
109	                        UPDATE certificate
110	                        SET status = 'SUPERSEDED', valid_flag = NULL, superseded_by = ?
111	                        WHERE id = ?
112	                        """, newCertificateId, oldCertificateId);
113	        if (updated != 1) {
114	            throw new IllegalStateException("旧证失效更新行数异常: " + updated);
115	        }
116	    }
117	
118	    /** 挂起证书转为有效（原子交接最后一步）。 */
119	    public void markValid(long certificateId) {
120	        int updated = jdbc.update(
121	                "UPDATE certificate SET status = 'VALID', valid_flag = 'Y' WHERE id = ?",
122	                certificateId);
123	        if (updated != 1) {
124	            throw new IllegalStateException("新证生效更新行数异常: " + updated);
125	        }
126	    }
127	
128	    /** 展期批准：与展期状态更新同事务修改有效期至。 */
129	    public void updateValidUntil(long certificateId, LocalDate newValidUntil) {
130	        int updated = jdbc.update(
131	                "UPDATE certificate SET valid_until = ? WHERE id = ? AND valid_flag = 'Y'",
132	                Date.valueOf(newValidUntil), certificateId);
133	        if (updated != 1) {
134	            throw new IllegalStateException("展期更新证书行数异常: " + updated);
135	        }
136	    }
137	
138	    /** 一般缺陷逾期未合格复查：证书失效。 */
139	    public void markExpired(long certificateId) {
140	        int updated = jdbc.update("""
141	                        UPDATE certificate SET status = 'EXPIRED', valid_flag = NULL
142	                        WHERE id = ? AND valid_flag = 'Y'
143	                        """, certificateId);
144	        if (updated != 1) {
145	            throw new IllegalStateException("证书失效更新行数异常: " + updated);
146	        }
147	    }
